import{_ as t,H as a,f as o,i}from"./chunks/framework.DLd0CbzH.js";const p=JSON.parse('{"title":"Calculator (Recipes)","description":"Creating product specification sheets, calculating production costs, and managing overheads in OmniCraft ERP.","frontmatter":{"title":"Calculator (Recipes)","description":"Creating product specification sheets, calculating production costs, and managing overheads in OmniCraft ERP.","order":6},"headers":[],"relativePath":"docs/spaces/production/calculator.md","filePath":"docs/spaces/production/calculator.md"}'),r={name:"docs/spaces/production/calculator.md"};function n(c,e,s,l,u,d){return a(),o("div",null,[...e[0]||(e[0]=[i('<div class="warning custom-block"><p class="custom-block-title">📌 Documentation Under Development</p><p><strong>Dear Users!</strong></p><p>Since OmniCraft ERP is currently in an active beta stage, with regular updates and expansions, the reference materials are also being updated gradually.</p><p>At this time, please treat the documentation as a guide—it is currently incomplete, may temporarily lack descriptions for certain features, or contain minor inaccuracies.</p></div><h1 id="🧮-calculator-recipes-cost-pricing" tabindex="-1">🧮 Calculator: Recipes &amp; Cost Pricing <a class="header-anchor" href="#🧮-calculator-recipes-cost-pricing" aria-label="Permalink to &quot;🧮 Calculator: Recipes &amp; Cost Pricing&quot;">​</a></h1><p>The <strong>&quot;Calculator&quot;</strong> tab is the primary intellectual core of the application. Here, you create templates (specification sheets/recipes) for your products and calculate their exact cost price.</p><p>The screen is divided into two modes (toggle at the top):</p><ol><li><strong>Batch Calculation</strong> — quickly estimate the cost price of a batch and launch it into production.</li><li><strong>Recipe Database</strong> — manage your catalog of product templates.</li></ol><hr><h2 id="📝-creating-a-new-recipe" tabindex="-1">📝 Creating a New Recipe <a class="header-anchor" href="#📝-creating-a-new-recipe" aria-label="Permalink to &quot;📝 Creating a New Recipe&quot;">​</a></h2><p>Switch to the <strong>&quot;Recipe Database&quot;</strong> mode and click <strong>&quot;Create Recipe&quot;</strong>. The recipe builder will open.</p><h3 id="_1-core-product-parameters" tabindex="-1">1. Core Product Parameters <a class="header-anchor" href="#_1-core-product-parameters" aria-label="Permalink to &quot;1. Core Product Parameters&quot;">​</a></h3><ul><li><strong>Name:</strong> For example, <em>“Bifold Wallet (Black)”</em>.</li><li><strong>Labor Time (hrs):</strong> Specify how many hours of your active hands-on time are required to manufacture a single unit. This figure is multiplied by the <em>Master Hourly Rate</em> (from Settings) to incorporate your labor value into the cost price.</li></ul><h3 id="_2-overhead-expenses-coefficients" tabindex="-1">2. Overhead Expenses (Coefficients) <a class="header-anchor" href="#_2-overhead-expenses-coefficients" aria-label="Permalink to &quot;2. Overhead Expenses (Coefficients)&quot;">​</a></h3><p>OmniCraft lets you flexibly manage indirect operating costs via the <strong>&quot;Configure Rate, Markup, and Overheads&quot;</strong> button. The program pulls global overhead norms from active Workspace Settings (e.g., equipment wear, rent, software). You can apply a <strong>coefficient</strong> (multiplier) to a specific product:</p><ul><li>If you craft a complex product that consumes a lot of glue, electricity, or machine wear, set the overhead coefficient to <code>1.5</code>.</li><li>If it is a simple item sewn entirely by hand without machinery, set the equipment wear coefficient to <code>0</code> to omit it from the cost.</li></ul><h3 id="_3-two-tiered-bill-of-materials-raw-materials-packaging" tabindex="-1">3. Two-Tiered Bill of Materials (Raw Materials &amp; Packaging) <a class="header-anchor" href="#_3-two-tiered-bill-of-materials-raw-materials-packaging" aria-label="Permalink to &quot;3. Two-Tiered Bill of Materials (Raw Materials &amp; Packaging)&quot;">​</a></h3><p>The recipe within the program is divided into two distinct tabs:</p><ul><li><strong>Product Raw Materials:</strong> Here, you add leather, thread, edge dye, or timber. These materials are always deducted when processing production orders on the Workbench.</li><li><strong>Packaging Assembly:</strong> You can configure packaging sets (for example, &quot;Standard&quot; — cardboard box + tissue paper, or &quot;Premium&quot; — wooden box + wax seal). Packaging materials <strong>are not</strong> deducted during production! They remain in warehouse stock until you actually sell the product and select which packaging set to pair it with.</li></ul><blockquote><p>Select a category, choose a material from active warehouse stock, specify the consumption per 1 unit (for example, <code>1.2 sq ft</code>), and click the <strong>&quot;+&quot; (Add)</strong> button.</p></blockquote><hr><h2 id="🧮-batch-calculation-launching-to-the-workbench" tabindex="-1">🧮 Batch Calculation &amp; Launching to the Workbench <a class="header-anchor" href="#🧮-batch-calculation-launching-to-the-workbench" aria-label="Permalink to &quot;🧮 Batch Calculation &amp; Launching to the Workbench&quot;">​</a></h2><p>Once your recipes are created, switch to the <strong>&quot;Batch Calculation&quot;</strong> mode.</p><ol><li>Click the search bar and select the desired product from your database.</li><li>Specify the <strong>Quantity</strong> (how many units you plan to manufacture).</li><li>Select the <strong>Packaging</strong> set (optional) — this allows you to see the complete cost of the product in its final gift-wrapped form.</li></ol><h3 id="cost-breakdown-block" tabindex="-1">Cost Breakdown Block <a class="header-anchor" href="#cost-breakdown-block" aria-label="Permalink to &quot;Cost Breakdown Block&quot;">​</a></h3><p>The program instantly calculates:</p><ul><li><strong>Raw Materials Cost:</strong> Pulled from the active MAC price at the current millisecond.</li><li><strong>Labor Cost:</strong> Your crafting time multiplied by your active rate.</li><li><strong>Overhead Expenses:</strong> Includes percentage and fixed overheads.</li><li><strong>Packaging Components.</strong></li></ul><h3 id="launching-into-production" tabindex="-1">Launching into Production <a class="header-anchor" href="#launching-into-production" aria-label="Permalink to &quot;Launching into Production&quot;">​</a></h3><p>Once you are satisfied with the figures, click the green <strong>&quot;Start Production&quot;</strong> button.</p><p><em>The program will verify warehouse stock:</em></p><ul><li>If materials are sufficient, the batch is instantly dispatched to the <strong>Production</strong> tab (Workbench).</li><li>If materials are insufficient, the program will display a <strong>Deficit List</strong> (showing exactly what is missing). You can cancel the action or force-schedule the batch onto the workbench anyway (it will remain queued in a &quot;waiting for procurement&quot; status).</li></ul><hr><h2 id="🗄️-recipe-database-management" tabindex="-1">🗄️ Recipe Database Management <a class="header-anchor" href="#🗄️-recipe-database-management" aria-label="Permalink to &quot;🗄️ Recipe Database Management&quot;">​</a></h2><p>In the &quot;Recipe Database&quot; mode, you see a clean table of all your templates, displaying manufacturing Labor Time, Overheads %, and the resulting net Cost Price.</p><ul><li><strong>Editing (✏️):</strong> You can modify a recipe at any time (add thread, change leather consumption). <em>Note: Modifying a recipe does not affect completed stock currently sitting on your Showcase; however, it will immediately apply to all new estimates and Workbench orders.</em></li><li><strong>Archiving (📦):</strong> If you discontinue an item, move it to the archive.</li></ul><div class="warning custom-block"><p class="custom-block-title">Archiving Blocked</p><p>The program will not allow you to archive a recipe if a batch of that product is currently active on the Workbench. You must first complete or cancel the production order.</p></div>',33)])])}const g=t(r,[["render",n]]);export{p as __pageData,g as default};
